{
  "references": [
    {
      "id": "R1",
      "summary_ko": "파란 셔츠를 입은 남성이 회색 셔츠를 입은 여성으로 무작위로 바뀜.",
      "claims": [
        {
          "id": "R1.S1",
          "evidence": "The blue shirt man randomly turns into a women with a grey shirt.",
          "symptom_ko": "파란 셔츠를 입은 남성이 회색 셔츠를 입은 여성으로 무작위로 변함",
          "role": "complaint"
        }
      ]
    }
  ],
  "candidates": [
    {
      "id": "C3",
      "summary_ko": "회색 상의와 어두운 반바지를 입은 사람이 중앙 분수 뒤에서 갑자기 나타나 물을 가로질러 왼쪽으로 이동함.",
      "target_evidence": "Person in grey top and dark shorts",
      "interaction_evidence": "behind the central fountain and moves leftward across the water",
      "change_evidence": "spontaneously appears",
      "scope": "individual"
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "target_relation": "same_interaction",
      "event_relation": "same_event_different_aspect",
      "description_consistency": "minor_discrepancy",
      "conflict_scope": "matched_claim",
      "reference_claim_ids": [
        "R1.S1"
      ],
      "reference_evidence": "The blue shirt man randomly turns into a women with a grey shirt.",
      "candidate_evidence": "Person in grey top and dark shorts spontaneously appears behind the central fountain and moves leftward across the water.",
      "shared_event_ko": "파란 셔츠 남성이 사라지고 회색 셔츠/상의를 입은 여성이 갑자기 나타나는 동일한 인물 변환/출현 현상을 다룹니다.",
      "coexistence_explanation_ko": "R1은 이전 인물(파란 셔츠 남성)이 회색 셔츠 여성으로 변환되는 전체 과정 관점에서 기술했고, C3은 그 결과로 회색 상의를 입은 인물이 갑자기 출현한 국면을 기술하여 두 설명이 동일한 이상 현상의 전후/부분 국면으로 공존할 수 있습니다.",
      "conflicts_ko": [
        "R1은 파란 셔츠 남성이 여성으로 변환된 것으로 표현한 반면, C3은 분수 뒤에서 회색 상의 인물이 갑자기 나타난 것으로 표현함"
      ],
      "reason_ko": "R1의 변환 결과로 생성된 '회색 셔츠 여성'과 C3의 '갑자기 나타난 회색 상의 인물'이 일치하며, 변환(turn into) 과정과 돌발 출현(spontaneously appears)은 동일 사건의 서로 다른 측면이자 결과적 출현을 포괄하므로 부분 사건/동일 사건의 다른 측면으로 성립합니다.",
      "event_link": "process_result",
      "separation_basis": "none"
    }
  ]
}
